let me=null, mode='login', view='chats', selected={type:'channel',name:'general',title:'گفت‌وگوی عمومی'}, socket=null, users=[], conversations=[], recorder=null, recordingStream=null, peer=null, localStream=null, pendingOffer=null, pendingIceCandidates=[], liveComments=[], callPeerId=null, liveStream=null, livePeers=new Map(), watchingLive=false;
