function conversationKey(){return selected.type==='conversation'?'conversation:'+selected.id:selected.type==='dm'?'dm:'+selected.id:'channel:'+(selected.name||'general')}
function updatePinnedBanner(messages=currentLoadedMessages){const bar=$('#pinned-message-banner');if(!bar)return;const pinned=[...(messages||[])].filter(m=>m.is_pinned);if(!pinned.length||pinnedBannerDismissed){bar.classList.add('hidden');return}const m=pinned[pinned.length-1];bar.dataset.messageId=m.id;$('#pinned-message-preview').textContent=(m.body|| (m.media_type==='image'?'تصویر':m.media_type==='audio'?'پیام صوتی':m.media_type==='video'?'ویدئو':m.media_url?'فایل':'پیام سنجاق‌شده')).slice(0,100);bar.classList.remove('hidden')}
