function canManageConversation(c){return !!c&&(me?.role==='admin'||c.owner_id===me?.id||['owner','admin'].includes(c.member_role));}
function renderGroupInfoTab(){const root=$('#group-info-tab-content');if(!root||!groupInfoData)return;const {conversation:c,members=[],media=[]}=groupInfoData;const tab=groupInfoTab;document.querySelectorAll('[data-info-tab]').forEach(b=>b.classList.toggle('active',b.dataset.infoTab===tab));if(tab==='members'){const manageable=canManageConversation(c);root.innerHTML=`<input id="group-member-search" class="group-member-search" placeholder="جست‌وجوی اعضا" aria-label="جست‌وجوی اعضا"><div class="group-members-list">${members.map(m=>`<article class="group-member-row" data-member-name="${escapeHtml((m.display_name+' '+m.username).toLowerCase())}"><div class="group-member-avatar">${m.avatar_url?`<img src="${escapeHtml(m.avatar_url)}" alt="">`:escapeHtml((m.display_name||m.username||'?').slice(0,1))}</div><div class="group-member-meta"><b>${escapeHtml(m.display_name)}</b><small>@${escapeHtml(m.username)} · ${m.role==='owner'?'مالک':m.role==='admin'?'مدیر':'عضو'}</small></div>${manageable&&m.id!==c.owner_id?`<button class="mini-btn danger" data-remove-member="${m.id}">حذف</button>`:''}</article>`).join('')||'<p class="group-info-empty">هنوز عضوی وجود ندارد.</p>'}</div>`;$('#group-member-search').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();root.querySelectorAll('.group-member-row').forEach(row=>row.classList.toggle('hidden',!row.dataset.memberName.includes(q)))});return;}const kind=tab;const items=media.filter(m=>m.media_type===kind);root.innerHTML=items.length?`<div class="group-media-grid">${items.map(m=>`<article class="group-media-item">${kind==='image'?`<img src="${escapeHtml(m.media_url)}" alt="تصویر ارسال‌شده" loading="lazy">`:kind==='video'?`<video src="${escapeHtml(m.media_url)}" controls preload="metadata"></video>`:kind==='audio'?`<audio src="${escapeHtml(m.media_url)}" controls preload="metadata"></audio>`:`<a href="${escapeHtml(m.media_url)}" target="_blank" rel="noopener">📎 ${escapeHtml(m.body||'دریافت فایل')}</a>`}<small>${escapeHtml(m.sender_name||'عضو')} · ${escapeHtml(new Date(m.created_at).toLocaleDateString('fa-IR'))}</small></article>`).join('')}</div>`:`<div class="group-info-empty"><div>🔗</div><p>هنوز ${kind==='image'?'تصویری':kind==='video'?'ویدئویی':kind==='audio'?'پیام صوتی':'فایلی'} در این بخش وجود ندارد.</p></div>`;}
async function openConversationInfo(){if(selected.type!=='conversation'){toast('اطلاعات اعضا برای گروه یا کانال در دسترس است.');return;}try{const d=await api(`/api/conversations/${selected.id}/details`);groupInfoData=d;groupInfoTab='members';const c=d.conversation;$('#group-info-name').textContent=c.name;$('#group-info-subtitle').textContent=`${c.type==='group'?'گروه':'کانال'} · ${d.members.length} عضو`;$('#group-info-description').textContent=c.description||'';$('#group-info-avatar').innerHTML=c.avatar_url?`<img src="${escapeHtml(c.avatar_url)}" alt="">`:c.type==='group'?'👥':'📣';const canManage=canManageConversation(c);$('#group-info-change-avatar').classList.toggle('hidden',!canManage);$('#group-info-add-member').classList.toggle('hidden',!canManage);renderGroupInfoTab();$('#conversation-info-modal').classList.remove('hidden');}catch(e){toast(e.message)}}

async function api(url, options={}) { const res=await fetch(url,{credentials:'same-origin',...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(options.headers||{})}}); const data=await res.json().catch(()=>({})); if(!res.ok) throw new Error(data.error||'خطایی رخ داد.'); return data; }
let toastTimer; function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3000)}
function setMode(next){mode=next;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('#display-wrap').classList.toggle('hidden',mode!=='register');$('#auth-submit').textContent=mode==='login'?'ورود به SSB':'ساخت حساب';}
