async function boot(){try{const d=await api('/api/me');me=d.user;$('#auth').classList.add('hidden');$('#app').classList.remove('hidden');$('#my-name').textContent='@'+me.username;$('#admin-open').classList.toggle('hidden',me.role!=='admin');$('#post-form').classList.toggle('hidden',me.role!=='admin');if($('#announcement-permission')) $('#announcement-permission').classList.toggle('hidden',me.role==='admin');await Promise.all([loadUsers(''),loadConversations(),loadChatPreviews()]);connectSocket();renderList();await openSelected()}catch(e){console.error('SSB boot error:',e);if(!me){$('#auth').classList.remove('hidden');$('#app').classList.add('hidden')}else{toast('ورود انجام شد، اما بارگذاری بخشی از صفحه ناموفق بود. صفحه را تازه‌سازی کن.')}}}
