let recordingTarget=null;$('#voice-record').addEventListener('click',async()=>{if(recorder&&recorder.state==='recording'){recorder.stop();$('#voice-record').textContent='🎙';return}try{recordingTarget=selected;recordingStream=await navigator.mediaDevices.getUserMedia({audio:true});const preferred=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(t=>window.MediaRecorder&&MediaRecorder.isTypeSupported?.(t));recorder=preferred?new MediaRecorder(recordingStream,{mimeType:preferred}):new MediaRecorder(recordingStream);const activeRecorder=recorder,chunks=[];activeRecorder.ondataavailable=e=>{if(e.data&&e.data.size)chunks.push(e.data)};activeRecorder.onerror=()=>toast('ضبط پیام صوتی با خطا روبه‌رو شد.');activeRecorder.onstop=async()=>{const mime=activeRecorder.mimeType||chunks[0]?.type||'audio/webm',ext=mime.includes('mp4')?'m4a':mime.includes('ogg')?'ogg':'webm',blob=new Blob(chunks,{type:mime});recordingStream?.getTracks().forEach(t=>t.stop());recordingStream=null;$('#voice-record').textContent='🎙';if(!blob.size){toast('صدایی ضبط نشد؛ دوباره تلاش کن.');return}try{const fd=new FormData();fd.append('file',blob,`voice-message.${ext}`);const d=await api('/api/upload',{method:'POST',body:fd});await sendMessage('',d.url,'audio',recordingTarget||selected);toast('پیام صوتی در گفتگو ارسال شد')}catch(err){toast(err.message)}};activeRecorder.start();$('#voice-record').textContent='⏹';toast('در حال ضبط؛ برای پایان و ارسال دوباره روی دکمه بزن')}catch(e){recordingStream?.getTracks().forEach(t=>t.stop());recordingStream=null;$('#voice-record').textContent='🎙';toast('برای ضبط پیام صوتی اجازه میکروفون بده و از localhost یا HTTPS استفاده کن')}});
