tListener('click',()=>$('#group-info-avatar-input').click());$('#group-info-avatar-input').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{const fd=new FormData();fd.append('file',file);const up=await api('/api/upload',{method:'POST',body:fd});const d=await api(`/api/conversations/${selected.id}/avatar`,{method:'PATCH',body:JSON.stringify({avatarUrl:up.url})});const i=conversations.findIndex(c=>c.id===selected.id);if(i>=0)conversations[i]={...conversations[i],...d.conversation};renderList();await openConversationInfo();setView();toast('عکس گروه یا کانال تغییر کرد.')}catch(err){toast(err.message)}});
$('#profile-open').addEventListener('click',()=>{$('#profile-name').value=me.display_name||'';$('#profile-bio').value=me.bio||'';$('#profile-avatar').value='';$('#profile-modal').classList.remove('hidden')});$('#profile-close').addEventListener('click',()=>$('#profile-modal').classList.add('hidden'));
$('#profile-save').addEventListener('click',async()=>{try{let avatarUrl=me.avatar_url||'';const file=$('#profile-avatar').files[0];if(file){if(!file.type.startsWith('image/'))throw new Error('فقط عکس انتخاب کن.');const up=await uploadFile(file);avatarUrl=up.url}const d=await api('/api/profile',{method:'PATCH',body:JSON.stringify({displayName:$('#profile-name').value,bio:$('#profile-bio').value,avatarUrl})});me=d.user;$('#my-name').textContent=me.display_name+' · @'+me.username;$('#profile-modal').classList.add('hidden');await loadUsers();renderList();toast('پروفایل ذخیره شد')}catch(e){toast(e.message)}});
$('#live-toggle').addEventListener('click',async()=>{const c=conversations.find(x=>x.id===selected.id);if(!c)return;try{const live=!c.live;if(live){liveStream=await navigator.mediaDevices.getUserMedia({audio:true,video:true});$('#live-video').srcObject=liveStream;$('#live-video').muted=true;$('#live-video').classList.add('watching');document.body.classList.add('live-fullscreen')}else{document.body.classList.remove('live-fullscreen');if(liveStream){liveStream.getTracks().forEach(t=>t.stop());liveStream=null}for(const p of livePeers.values())p.close();livePeers.clear();$('#live-video').srcObject=null;$('#live-video').classList.remove('watching')}await api(`/api/conversations/${c.id}/live`,{method:'POST',body:JSON.stringify({live})});c.live=live;setView();toast(live?'پخش زنده تصویری آغاز شد':'پخش زنده متوقف شد')}catch(e){if(liveStream){liveStream.getTracks().forEach(t=>t.stop());liveStream=null}toast('برای پخش زنده باید به دوربین و میکروفون اجازه بدهی و از localhost یا HTTPS استفاده کنی.')}});
$('#live-watch').addEventListener('click',async()=>{const c=conversations.find(x=>x.id===selected.id);if(!c?.live)return;try{watchingLive=true;$('#live-video').muted=false;$('#live-video').classList.add('watching');document.body.classList.add('live-fullscreen');const pc=new RTCPeerConnection(rtcConfig);livePeers.set((c.live_host_id||c.owner_id),pc);pc.ontrack=e=>{$('#live-video').srcObject=e.streams[0];$('#live-video').play().catch(()=>{})};pc.onicecandidate=e=>{if(e.candidate)socket.emit('live-signal',{targetId:(c.live_host_id||c.owner_id),conversationId:c.id,signal:{type:'candidate',candidate:e.candidate}})};const offer=await pc.createOffer();await pc.setLocalDescription(offer);socket.emit('live-signal',{targetId:(c.live_host_id||c.owner_id),conversationId:c.id,signal:{type:'offer',sdp:offer}});toast('در حال اتصال به پخش زنده…')}catch(e){toast('اتصال به پخش زنده ناموفق بود.')}});
async function handleLiveSignal(d){if(!d?.signal)return;const c=conversations.find(x=>x.id===d.conversationId);if(!c)return;try{if(d.signal.type==='offer'&&liveStream&&((c.live_host_id||c.owner_id)===me.id||me.role==='admin')){const pc=new RTCPeerConnection(rtcConfig);livePeers.set(d.fromId,pc);liveStream.getTracks().forEach(t=>pc.addTrack(t,liveStream));pc.onicecandidate=e=>{if(e.candidate)socket.emit('live-signal',{targetId:d.fromId,conversationId:c.id,signal:{type:'candidate',candidate:e.candidate}})};await pc.setRemoteDescription(new RTCSessionDescription(d.signal.sdp));const answer=await pc.createAnswer();await pc.setLocalDescription(answer);socket.emit('live-signal',{targetId:d.fromId,conversationId:c.id,signal:{type:'answer',sdp:answer}})}else{const pc=livePeers.get(d.fromId)||livePeers.get(c.live_host_id||c.owner_id);if(!pc)return;if(d.signal.type==='answer')await pc.setRemoteDescription(new RTCSessionDescription(d.signal.sdp));else if(d.signal.type==='candidate')await pc.addIceCandidate(new RTCIceCandidate(d.signal.candidate))}}catch(e){console.error('live signaling',e)}}
$('#live-chat-form').addEventListener('submit',e=>{e.preventDefault();const body=$('#live-chat-input').value.trim();if(!body||selected.type!=='conversation')return;socket.emit('live-comment',{conversationId:selected.id,body});$('#live-chat-input').value=''});
$('#live-fullscreen-close').addEventListener('click',()=>document.body.classList.remove('live-fullscreen'));
$('#live-emoji-buttons').addEventListener('click',e=>{const b=e.target.closest('[data-live-emoji]');if(!b)return;const input=$('#live-chat-input');input.value+=b.dataset.liveEmoji;input.focus()});
function renderLiveComments(){$('#live-comments').innerHTML=liveComments.slice(-50).map(c=>`<div><b>${escapeHtml(c.username)}:</b> ${escapeHtml(c.body)}</div>`).join('');$('#live-comments').scrollTop=$('#live-comments').scrollHeight}
// One-to-one WebRTC calls. For internet-wide reliability configure a TURN server on the deployed instance.
const rtcConfig={iceServers:[{urls:'stun:stun.l.google.com:19302'}]};
async function startCall(callType){if(selected.type!=='dm')return;callPeerId=selected.id;try{localStream=await navigator.mediaDevices.getUserMedia({audio:true,video:callType==='video'});peer=new RTCPeerConnection(rtcConfig);localStream.getTracks().forEach(t=>peer.addTrack(t,localStream));peer.ontrack=e=>{const stream=e.streams[0];if(callType==='video')$('#remote-video').srcObject=stream;else $('#remote-audio').srcObject=stream};peer.onicecandidate=e=>{if(e.candidate)socket.emit('call-signal',{targetId:selected.id,callType,signal:{type:'candidate',candidate:e.candidate}})};$('#local-video').srcObject=localStream;$('#call-title').textContent='در حال تماس با '+selected.title;$('#call-overlay').classList.remove('hidden');const offer=await peer.createOffer();await peer.setLocalDescription(offer);socket.emit('call-signal',{targetId:selected.id,callType,signal:{type:'offer',sdp:offer}})}catch(e){toast('دسترسی میکروفون/دوربین ناموفق بود. از localhost یا HTTPS استفاده کن.');endCall()}}
async function handleCallSignal(d){if(!d||!d.signal)return;try{if(d.signal.type==='offer'){callPeerId=d.fromId;pendingOffer=d;$('#call-title').textContent='تماس ورودی از '+d.fromName;$('#call-answer').classList.remove('hidden');$('#call-overlay').classList.remove('hidden');return}if(d.signal.type==='candidate'){if(peer?.remoteDescription){await peer.addIceCandidate(new RTCIceCandidate(d.signal.candidate))}else if(d.signal.candidate){pendingIceCandidates.push(d.signal.candidate)}return}if(d.signal.type==='answer'&&peer){await peer.setRemoteDescription(new RTCSessionDescription(d.signal.sdp));for(const candidate of pendingIceCandidates.splice(0)){try{await peer.addIceCandidate(new RTCIceCandidate(candidate))}catch(err){console.warn('ICE candidate skipped',err)}}return}if(d.signal.type==='hangup'){endCall(false);toast('تماس پایان یافت')}}catch(e){console.error(e)}}
$('#call-audio').addEventListener('click',()=>startCall('audio'));$('#call-video').addEventListener('click',()=>startCall('video'));
$('#call-answer').addEventListener('click',async()=>{if(!pendingOffer)return;try{const type=pendingOffer.callType;localStream=await navigator.mediaDevices.getUserMedia({audio:true,video:type==='video'});peer=new RTCPeerConnection(rtcConfig);localStream.getTracks().forEach(t=>peer.addTrack(t,localStream));peer.ontrack=e=>{if(type==='video')$('#remote-video').srcObject=e.streams[0];else $('#remote-audio').srcObject=e.streams[0]};peer.onicecandidate=e=>{if(e.candidate)socket.emit('call-signal',{targetId:pendingOffer.fromId,callType:type,signal:{type:'candidate',candidate:e.candidate}})};await peer.setRemoteDescription(new RTCSessionDescription(pendingOffer.signal.sdp));for(const candidate of pendingIceCandidates.splice(0)){try{await peer.addIceCandidate(new RTCIceCandidate(candidate))}catch(err){console.warn('ICE candidate skipped',err)}}const answer=await peer.createAnswer();await peer.setLocalDescription(answer);socket.emit('call-signal',{targetId:pendingOffer.fromId,callType:type,signal:{type:'answer',sdp:answer}});pendingOffer=null;$('#call-answer').classList.add('hidden')}catch(e){toast('پاسخ به تماس ناموفق بود.');endCall()}});
function endCall(notify=true){if(notify&&callPeerId)socket?.emit('call-signal',{targetId:callPeerId,callType:'audio',signal:{type:'hangup'}});callPeerId=null;if(peer){peer.close();peer=null}if(localStream){localStream.getTracks().forEach(t=>t.stop());localStream=null}$('#local-video').srcObject=null;$('#remote-video').srcObject=null;$('#remote-audio').srcObject=null;$('#call-overlay').classList.add('hidden');$('#call-answer').classList.add('hidden');pendingOffer=null;pendingIceCandidates=[]}
$('#call-hangup').addEventListener('click',()=>endCall());$('#call-close').addEventListener('click',()=>endCall());
async function loadPosts(){try{const d=await api('/api/channel');$('#posts').innerHTML=d.posts.map(p=>`<article class="post" data-post-id="${p.id}"><div class="post-body">${escapeHtml(p.body)}</div><small>${escapeHtml(p.author_name)} · ${new Date(p.created_at).toLocaleString('fa-IR')}</small>${me?.role==='admin'?`<div class="post-admin-actions"><button class="mini-btn" data-post-edit="${p.id}">✏️ ویرایش</button><button class="mini-btn danger" data-post-delete="${p.id}">🗑️ حذف</button></div>`:''}</article>`).join('')||'<p class="muted">هنوز اطلاعیه‌ای منتشر نشده است.</p>'}catch(e){toast(e.message)}}
$('#post-form').addEventListener('submit',async e=>{e.preventDefault();const ta=e.currentTarget.elements.body;try{await api('/api/channel',{method:'POST',body:JSON.stringify({body:ta.value})});ta.value='';await loadPosts();toast('اطلاعیه منتشر شد.')}catch(err){toast(err.message)}});

$('#posts').addEventListener('click',async e=>{const edit=e.target.closest('[data-post-edit]'),del=e.target.closest('[data-post-delete]');if(me?.role!=='admin')return;try{if(edit){const id=Number(edit.dataset.postEdit),el=edit.closest('.post'),old=el.querySelector('.post-body').textContent,next=prompt('ویرایش اطلاعیه',old);if(next===null)return;await api('/api/channel/'+id,{method:'PATCH',body:JSON.stringify({body:next})});await loadPosts();toast('اطلاعیه ویرایش شد')}else if(del){const id=Number(del.dataset.postDelete);if(!confirm('این اطلاعیه حذف شود؟'))return;await api('/api/channel/'+id,{method:'DELETE'});await loadPosts();toast('اطلاعیه حذف شد')}}catch(err){toast(err.message)}});
$('#conversation-avatar-change').addEventListener('click',()=>$('#conversation-avatar-input').click());
$('#conversation-avatar-input').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(!file.type.startsWith('image/'))throw new Error('لطفاً یک عکس انتخاب کن.');const up=await uploadFile(file);const d=await api('/api/conversations/'+selected.id+'/avatar',{method:'PATCH',body:JSON.stringify({avatarUrl:up.url})});const i=conversations.findIndex(c=>c.id===selected.id);if(i>=0)conversations[i]={...conversations[i],...d.conversation};renderList();setView();toast('عکس گروه/کانال تغییر کرد')}catch(err){toast(err.message)}});
$('#logout').addEventListener('click',async()=>{await api('/api/logout',{method:'POST'});if(socket)socket.disconnect();endCall(false);me=null;$('#app').classList.add('hidden');$('#auth').classList.remove('hidden')});
$('#admin-open').addEventListener('click',()=>{$('#admin-modal').classList.remove('hidden');loadAdmin()});$('#admin-close').addEventListener('click',()=>$('#admin-modal').classList.add('hidden'));$('#admin-modal').addEventListener('click',e=>{if(e.target.id==='admin-modal')$('#admin-modal').classList.add('hidden')});
async function loadAdmin(){const box=$('#admin-content');box.innerHTML='<p>در حال بارگذاری…</p>';try{const [d,c]=await Promise.all([api('/api/admin/overview'),api('/api/admin/conversations')]);box.innerHTML=`<div class="stats"><div class="stat"><small>کل کاربران</small><b>${d.stats.users}</b></div><div class="stat"><small>مسدودشده‌ها</small><b>${d.stats.banned}</b></div><div class="stat"><small>کل پیام‌ها</small><b>${d.stats.messages}</b></div><div class="stat"><small>گروه/کانال</small><b>${c.conversations.length}</b></div></div><h3>مدیریت کاربران</h3><div class="table-wrap"><table><thead><tr><th>کاربر</th><th>نقش</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${d.users.map(u=>`<tr><td>${escapeHtml(u.display_name)}<br><small>@${escapeHtml(u.username)}</small></td><td>${u.role==='admin'?'مدیر':'کاربر'}</td><td>${u.banned?'مسدود':'فعال'}</td><td>${u.id===me.id?'حساب شما':`<button class="mini-btn ${u.banned?'':'danger'}" data-action="ban" data-id="${u.id}" data-value="${!u.banned}">${u.banned?'رفع مسدودی':'مسدودسازی'}</button><button class="mini-btn" data-action="role" data-id="${u.id}" data-value="${u.role==='admin'?'user':'admin'}">${u.role==='admin'?'حذف مدیریت':'ارتقای مدیر'}</button>`}</td></tr>`).join('')}</tbody></table></div><h3>مدیریت گروه‌ها و کانال‌ها</h3><div class="table-wrap"><table><thead><tr><th>نام</th><th>نوع</th><th>سازنده</th><th>اعضا</th><th>وضعیت زنده</th><th>عملیات</th></tr></thead><tbody>${c.conversations.map(x=>`<tr><td>${escapeHtml(x.name)}</td><td>${x.type==='group'?'گروه':'کانال'}</td><td>${escapeHtml(x.owner_name)}</td><td>${x.members}</td><td>${x.live?'در حال پخش':'خاموش'}</td><td><button class="mini-btn danger" data-delete-conv="${x.id}">حذف</button>${x.live?`<button class="mini-btn danger" data-live-conv="${x.id}" data-value="false">توقف زنده</button>`:'<small>شروع از داخل گفت‌وگو</small>'}</td></tr>`).join('')}</tbody></table></div><h3>آخرین گفت‌وگوهای خصوصی (نظارت مدیر)</h3><p class="muted small">مدیر می‌تواند پیام‌های خصوصی ذخیره‌شده را مشاهده کند؛ این قابلیت باید در سیاست حریم خصوصی سرویس اعلام شود.</p><ul class="log-list">${c.recentPrivate.map(m=>`<li>@${escapeHtml(m.sender)} → @${escapeHtml(m.recipient)} · ${escapeHtml(m.media_type==='text'?(m.body||'رسانه'):m.media_type)} <small>${escapeHtml(m.created_at)}</small></li>`).join('')}</ul><h3>گزارش فعالیت اخیر</h3><ul class="log-list">${d.logs.map(l=>`<li>${escapeHtml(l.action)} — ${escapeHtml(l.username||'سیستم')} — ${escapeHtml(l.details)} <small>${escapeHtml(l.created_at)}</small></li>`).join('')}</ul>`;
box.querySelectorAll('[data-action]').forEach(btn=>btn.addEventListener('click',async()=>{try{const payload=btn.dataset.action==='ban'?{banned:btn.dataset.value==='true'}:{role:btn.dataset.value};await api('/api/admin/users/'+btn.dataset.id,{method:'PATCH',body:JSON.stringify(payload)});toast('تغییرات ذخیره شد.');await loadAdmin();await loadUsers();renderList()}catch(e){toast(e.message)}}));box.querySelectorAll('[data-delete-conv]').forEach(btn=>btn.addEventListener('click',async()=>{if(!confirm('این گروه/کانال و پیام‌های آن حذف شود؟'))return;try{await api('/api/admin/conversations/'+btn.dataset.deleteConv,{method:'PATCH',body:JSON.stringify({delete:true})});await loadAdmin();await loadConversations();renderList();toast('گروه/کانال حذف شد')}catch(e){toast(e.message)}}));box.querySelectorAll('[data-live-conv]').forEach(btn=>btn.addEventListener('click',async()=>{try{await api('/api/admin/conversations/'+btn.dataset.liveConv,{method:'PATCH',body:JSON.stringify({live:btn.dataset.value==='true'})});await loadAdmin();await loadConversations();renderList()}catch(e){toast(e.message)}}));}catch(e){box.innerHTML=`<p>${escapeHtml(e.message)}</p>`}}
boot();
